UPDATE public.game_cards c SET answer=a.correct FROM answers a WHERE c.trip_id IS NULL AND c.game_number=5 AND c.created_at >= '2026-10-04 03:06:43+00' AND c.prompt ILIKE '%'||a.question||'%';